import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const dict={en:{level:'LEVEL',resources:'Resources',dailyQuest:'Daily quest',buildYourWorld:'BUILD YOUR WORLD',chooseTile:'Choose a tile',field:'Field',forest:'Forest',water:'Water',farm:'Farm',coast:'Coast',mountain:'Mountain',build:'Build',tapWorld:'Tap a glowing space to place',rotate:'Rotate',gather:'Gather',market:'Market',missions:'Goals',continue:'Continue your world'},pt:{level:'NÍVEL',resources:'Recursos',dailyQuest:'Missão diária',buildYourWorld:'CONSTRUA SEU MUNDO',chooseTile:'Escolha um terreno',field:'Campo',forest:'Floresta',water:'Água',farm:'Fazenda',coast:'Costa',mountain:'Montanha',build:'Construir',tapWorld:'Toque em um espaço brilhante',rotate:'Girar',gather:'Coletar',market:'Mercado',missions:'Metas',continue:'Continuar seu mundo'}};
const tileDefs={field:{color:0x9fc66e,cost:0,res:{wheat:2,flowers:1}},forest:{color:0x4f9b72,cost:25,res:{wood:3,fruits:1}},water:{color:0x59bdc5,cost:25,res:{water:4,fish:2}},farm:{color:0xd9b86a,cost:40,res:{wheat:4,vegetables:2}},coast:{color:0xe9c77f,cost:35,res:{clay:2,fish:1}},mountain:{color:0x9ba99b,cost:50,res:{stone:3,minerals:1}}};
const resources=['wood','stone','water','fish','wheat','vegetables','fruits','flowers','clay','minerals'];
const itemEmoji={wood:'🪵',stone:'🪨',water:'💧',fish:'🐟',wheat:'🌾',vegetables:'🥕',fruits:'🍎',flowers:'🌸',clay:'🧱',minerals:'💎'};
const buildings={house:{name:'Cottage',emoji:'🏡',cost:{wood:8,stone:3},coins:25,pop:3},farmhouse:{name:'Farmstead',emoji:'🌻',cost:{wood:10,wheat:4},coins:35,pop:1},bridge:{name:'Little bridge',emoji:'🌉',cost:{wood:12,stone:4},coins:30},market:{name:'Market stall',emoji:'🧺',cost:{wood:10,fruits:3},coins:45},mill:{name:'Windmill',emoji:'🌬️',cost:{wood:14,stone:7},coins:55,production:'wheat'},warehouse:{name:'Storehouse',emoji:'🏠',cost:{wood:12,stone:5},coins:50}};
const defaultState=()=>({tiles:{'0,0':'field','1,0':'forest','0,1':'water','-1,1':'field','-1,0':'coast','0,-1':'mountain'},buildings:{'0,0':'house','1,0':'farmhouse'},resources:{wood:18,stone:12,water:10,fish:4,wheat:8,vegetables:3,fruits:3,flowers:2,clay:4,minerals:1},coins:120,stars:3,level:1,xp:0,mission:0,harvests:0,rotation:0,language:'en',sound:true,last:Date.now(),hasPlayed:false});
let state;try{state={...defaultState(),...JSON.parse(localStorage.getItem('terraHexaSave')||'{}')};state.resources={...defaultState().resources,...(state.resources||{})};state.tiles=state.tiles||defaultState().tiles;state.buildings=state.buildings||{};}catch{state=defaultState()}
let scene,camera,renderer,raycaster,pointer,worldGroup,groundPlane,selected='field',mode='tile',rotate=0,zoom=8.6,camAngle=0,selectedCell=null,hoverCell=null,clock=new THREE.Clock(),tileMeshes=new Map(),decorations=[],toastTimer,modalOpen=false,worldReady=false;
const mat=(color,roughness=.86)=>new THREE.MeshStandardMaterial({color,roughness,flatShading:true});
const mats={grass:mat(0x9fc66e),forest:mat(0x4f9b72),water:mat(0x56b9c3),farm:mat(0xd5b563),coast:mat(0xe9c57d),mountain:mat(0x99a79b),side:mat(0x7f9b61),white:mat(0xfff0d7),wood:mat(0x986c46),roof:mat(0xdf8a6c),pink:mat(0xe998a7),dark:mat(0x46745a),path:mat(0xd9cf9d),blue:mat(0x76c7ce)};
function init3D(){const mount=$('#scene-mount');scene=new THREE.Scene();scene.background=new THREE.Color(0xcbe9d8);scene.fog=new THREE.Fog(0xcbe9d8,15,34);camera=new THREE.OrthographicCamera(-6,6,9,-9,.1,100);camera.position.set(9,12,10);camera.lookAt(0,0,0);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(mount.clientWidth,mount.clientHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;mount.appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight(0xf4fff0,0x628c76,2));const sun=new THREE.DirectionalLight(0xfff2d4,3.2);sun.position.set(-7,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);worldGroup=new THREE.Group();scene.add(worldGroup);groundPlane=new THREE.Mesh(new THREE.PlaneGeometry(200,200),mat(0xbde0c6));groundPlane.rotation.x=-Math.PI/2;groundPlane.position.y=-.3;worldGroup.add(groundPlane);raycaster=new THREE.Raycaster();pointer=new THREE.Vector2();rebuildWorld();resize();renderer.domElement.addEventListener('pointerdown',onWorldPointer);renderer.domElement.addEventListener('pointermove',onWorldMove);renderer.domElement.addEventListener('pointerup',()=>{});renderer.domElement.addEventListener('wheel',e=>{zoom=Math.max(6,Math.min(14,zoom+e.deltaY*.008));updateCamera()},{passive:true});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('touchstart',()=>{}, {passive:true});window.addEventListener('resize',resize);animate();worldReady=true;}
function resize(){if(!renderer)return;const w=$('#scene-mount').clientWidth,h=$('#scene-mount').clientHeight;renderer.setSize(w,h);const aspect=w/h;camera.left=-zoom*aspect/2;camera.right=zoom*aspect/2;camera.top=zoom/2;camera.bottom=-zoom/2;camera.updateProjectionMatrix();}
function updateCamera(){if(!camera)return;const w=$('#scene-mount').clientWidth,h=$('#scene-mount').clientHeight,aspect=w/h;camera.left=-zoom*aspect/2;camera.right=zoom*aspect/2;camera.top=zoom/2;camera.bottom=-zoom/2;camera.updateProjectionMatrix();camera.position.set(Math.sin(camAngle)*12,13,Math.cos(camAngle)*12);camera.lookAt(0,0,0)}
function coord(q,r){const s=1.16;return new THREE.Vector3(Math.sqrt(3)*(q+r/2)*s,0,1.5*r*s)}
function key(q,r){return `${q},${r}`}
function clearGroup(g){while(g.children.length){const o=g.children.pop();if(o.geometry)o.geometry.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose()}}
function rebuildWorld(){if(!worldGroup)return;for(const c of [...worldGroup.children])if(c!==groundPlane){worldGroup.remove(c);if(c.geometry)c.geometry.dispose()}tileMeshes.clear();decorations=[];Object.entries(state.tiles).forEach(([k,type])=>{const [q,r]=k.split(',').map(Number);makeTile(q,r,type)});Object.entries(state.buildings).forEach(([k,type])=>{const [q,r]=k.split(',').map(Number);makeBuilding(q,r,type)});makeWaterfallAndLife();}
function makeTile(q,r,type){const p=coord(q,r),color=tileDefs[type]?.color||tileDefs.field.color;const base=new THREE.Mesh(new THREE.CylinderGeometry(1.16,1.16,.33,6,1),mat(color));base.rotation.y=Math.PI/6;base.position.set(p.x,-.12,p.z);base.receiveShadow=true;base.castShadow=true;base.userData={q,r,type,interactive:true};worldGroup.add(base);tileMeshes.set(key(q,r),base);const topY=.055;const top=new THREE.Mesh(new THREE.CylinderGeometry(1.12,1.12,.08,6,1),mat(color));top.rotation.y=Math.PI/6;top.position.set(p.x,topY,p.z);top.userData={q,r,type,interactive:true};worldGroup.add(top);decorateTile(p,type,q,r);}
function addProp(geo,material,x,y,z,group=worldGroup){const mesh=new THREE.Mesh(geo,material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh}
function tree(x,z,scale=1,flower=false){const g=new THREE.Group();g.position.set(x,.08,z);g.scale.setScalar(scale);const trunk=addProp(new THREE.CylinderGeometry(.09,.13,.52,5),mats.wood,0,.26,0,g);const crown=addProp(new THREE.IcosahedronGeometry(.42,0),flower?mats.pink:mat(0x428e60),0,.69,0,g);crown.scale.set(1,1.18,1);decorations.push({obj:g,speed:1+Math.random(),phase:Math.random()*5,sway:.035});worldGroup.add(g)}
function flower(x,z,color=0xe39c8b){const stem=addProp(new THREE.CylinderGeometry(.018,.025,.24,4),mat(0x569063),x,.17,z);const bloom=addProp(new THREE.IcosahedronGeometry(.09,0),mat(color),x,.31,z);bloom.scale.y=.7;}
function decorateTile(p,type,q,r){const seed=Math.abs(q*31+r*19+37);const rand=n=>((seed+n*13)%17)/17;if(type==='forest'){tree(p.x-.35,p.z-.14,.8+rand(1)*.25);tree(p.x+.34,p.z+.22,.75+rand(2)*.28,rand(3)>.65);tree(p.x+.1,p.z-.4,.62)}else if(type==='field'){for(let i=0;i<4;i++){const x=p.x+(rand(i)*1.1-.55),z=p.z+(rand(i+5)*.8-.4);flower(x,z,[0xe7a6a0,0xffd77e,0xf5f2d8][i%3])}}else if(type==='farm'){for(let row=0;row<3;row++)for(let i=0;i<4;i++){const x=p.x-.62+i*.4,z=p.z-.34+row*.34;const stalk=addProp(new THREE.CylinderGeometry(.035,.045,.24,4),mat(0x849e42),x,.18,z);stalk.rotation.z=.12;addProp(new THREE.SphereGeometry(.09,5,4),mat(0xe5bd59),x,.31,z)}}else if(type==='coast'){for(let i=0;i<3;i++){const rock=addProp(new THREE.DodecahedronGeometry(.13,0),mat(0xe5d6b3),p.x-.45+i*.35,.12,p.z+.15)}}else if(type==='mountain'){for(let i=0;i<3;i++){const rock=addProp(new THREE.ConeGeometry(.31+rand(i)*.08,.65+rand(i+3)*.35,5),mat(i===1?0xb7c5b7:0x85968c),p.x-.36+i*.34,.34,p.z+(i%2?.13:-.1));rock.rotation.y=rand(i+6)*1.8}}else if(type==='water'){const ripple=addProp(new THREE.TorusGeometry(.23,.018,4,12),mat(0xb6f0dc),p.x,.11,p.z);ripple.rotation.x=Math.PI/2;decorations.push({obj:ripple,water:true,phase:rand(2)*5})}}
function makeBuilding(q,r,type){const p=coord(q,r),def=buildings[type];if(!def)return;const g=new THREE.Group();g.position.set(p.x,.1,p.z);if(type==='house'||type==='farmhouse'||type==='warehouse'){const w=type==='warehouse'?.56:.45,h=type==='house'?.48:.35;addProp(new THREE.BoxGeometry(w,h,.42),mat(type==='farmhouse'?0xf3dcaa:0xffe7c7),0,h/2,0,g);const roof=addProp(new THREE.ConeGeometry(.42,.42,4),mat(type==='farmhouse'?0xd5865d:0xc9745c),0,h+.18,0,g);roof.rotation.y=Math.PI/4;addProp(new THREE.BoxGeometry(.11,.22,.025),mat(0x79a8a2),.12,.18,.218,g)}else if(type==='mill'){const body=addProp(new THREE.CylinderGeometry(.26,.32,.6,6),mat(0xf4e4bc),0,.3,0,g);const roof=addProp(new THREE.ConeGeometry(.36,.3,6),mat(0xd78365),0,.73,0,g);const rotor=new THREE.Group();rotor.position.set(0,.52,.32);for(let i=0;i<4;i++){const blade=addProp(new THREE.BoxGeometry(.09,.58,.035),mat(0xfff3d9),0,.27,0,rotor);blade.rotation.z=i*Math.PI/2; }g.add(rotor);decorations.push({obj:rotor,rotate:true})}else if(type==='market'){addProp(new THREE.BoxGeometry(.6,.11,.4),mat(0xa8784e),0,.3,0,g);addProp(new THREE.ConeGeometry(.5,.32,4),mat(0xe8847a),0,.56,0,g).rotation.y=Math.PI/4;for(let i=0;i<3;i++)addProp(new THREE.SphereGeometry(.08,5,4),mat([0xed7669,0xe5c653,0x7bb56a][i]),-.18+i*.18,.4,0,g)}else if(type==='bridge'){for(let i=0;i<4;i++)addProp(new THREE.BoxGeometry(.16,.08,.72),mat(0x9d7752),-.3+i*.2,.2,0,g)}worldGroup.add(g);}

function makeWaterfallAndLife(){// tiny floating life makes the diorama feel inhabited
  const boat=new THREE.Group();boat.position.set(1.05,.22,1.05);const hull=addProp(new THREE.BoxGeometry(.52,.12,.24),mat(0xb87554),0,0,0,boat);hull.rotation.z=.05;addProp(new THREE.BoxGeometry(.22,.2,.04),mat(0xf6e6c6),.04,.16,0,boat);worldGroup.add(boat);decorations.push({obj:boat,boat:true,phase:0});
  for(let i=0;i<3;i++){const bird=new THREE.Group();const body=addProp(new THREE.SphereGeometry(.09,6,5),mat(0xfff4dd),0,0,0,bird);body.scale.set(1,.55,.5);const wing=addProp(new THREE.BoxGeometry(.15,.025,.08),mat(0xffffff),.02,.04,0,bird);bird.position.set(-2.2+i*.55,2.7,-1.7);scene.add(bird);decorations.push({obj:bird,bird:true,phase:i*2})}
  for(let i=0;i<2;i++){const g=new THREE.Group();g.position.set(-.42+i*.82,.13,.98);addProp(new THREE.SphereGeometry(.13,7,5),mat(i?0xeed6aa:0xf2f1e4),0,.1,0,g);addProp(new THREE.SphereGeometry(.09,6,5),mat(0xeee7d7),.12,.21,0,g);addProp(new THREE.ConeGeometry(.035,.12,4),mat(0xe98e6b),.22,.19,0,g);worldGroup.add(g);decorations.push({obj:g,walk:true,phase:i*3})}
}
function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();decorations.forEach(d=>{if(d.rotate)d.obj.rotation.z=t*.75;if(d.water)d.obj.scale.setScalar(.85+Math.sin(t*1.6+d.phase)*.18);if(d.sway)d.obj.rotation.z=Math.sin(t*d.speed+d.phase)*d.sway;if(d.boat){d.obj.position.x=1.05+Math.sin(t*.38)*.25;d.obj.position.z=1.05+Math.cos(t*.32)*.18;d.obj.rotation.y=Math.sin(t*.38)*.18}if(d.bird){d.obj.position.x=-2.2+Math.sin(t*.35+d.phase)*.7;d.obj.position.y=2.7+Math.sin(t*4+d.phase)*.08;d.obj.rotation.z=Math.sin(t*4+d.phase)*.18}if(d.walk){d.obj.position.x+=Math.sin(t*.75+d.phase)*.0008;d.obj.rotation.y=Math.sin(t*.8+d.phase)*.2}});if(renderer)renderer.render(scene,camera)}
function nearestAxial(point){const s=1.16;const q=(Math.sqrt(3)/3*point.x-1/3*point.z)/s,r=(2/3*point.z)/s;let x=q,z=r,y=-x-z;let rx=Math.round(x),ry=Math.round(y),rz=Math.round(z);const dx=Math.abs(rx-x),dy=Math.abs(ry-y),dz=Math.abs(rz-z);if(dx>dy&&dx>dz)rx=-ry-rz;else if(dy>dz)ry=-rx-rz;else rz=-rx-ry;return [rx,rz]}
function neighbors(q,r){return [[1,0],[1,-1],[0,-1],[-1,0],[-1,1],[0,1]].map(([a,b])=>[q+a,r+b])}
function isAdjacent(q,r){return neighbors(q,r).some(([a,b])=>state.tiles[key(a,b)])}
function eventPoint(e){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(e.clientX-rect.left)/rect.width*2-1;pointer.y=-(e.clientY-rect.top)/rect.height*2+1;raycaster.setFromCamera(pointer,camera)}
let ghost;
function onWorldMove(e){eventPoint(e);const hit=raycaster.intersectObject(groundPlane)[0];if(!hit)return;const [q,r]=nearestAxial(hit.point);const k=key(q,r);hoverCell=k;if(state.tiles[k]||!isAdjacent(q,r)){if(ghost){worldGroup.remove(ghost);ghost=null}return}if(!ghost){ghost=new THREE.Mesh(new THREE.CylinderGeometry(1.12,1.12,.1,6),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.38,depthWrite:false}));ghost.rotation.y=Math.PI/6;worldGroup.add(ghost)}const p=coord(q,r);ghost.position.set(p.x,.03,p.z);ghost.material.color.setHex(mode==='tile'?tileDefs[selected].color:0x9fe0a2);ghost.material.opacity=.55;}
function onWorldPointer(e){if(e.button!==undefined&&e.button!==0)return;eventPoint(e);const hits=raycaster.intersectObjects([...tileMeshes.values()],false);if(hits.length){const {q,r,type}=hits[0].object.userData;selectedCell=[q,r];if(mode==='remove'){if(key(q,r)==='0,0'){showToast('Your first tile is here to stay 🌱');return}delete state.tiles[key(q,r)];delete state.buildings[key(q,r)];save();rebuildWorld();showToast('Tile removed');return}if(mode==='gather'){collectFrom(q,r,type);return}if(mode==='build'){placeBuildingAt(q,r);return}if(e.pointerType==='touch'||e.detail>0){collectFrom(q,r,type);return}}
const hit=raycaster.intersectObject(groundPlane)[0];if(!hit)return;const [q,r]=nearestAxial(hit.point);if(state.tiles[key(q,r)]){if(mode==='gather')collectFrom(q,r,state.tiles[key(q,r)]);return}if(!isAdjacent(q,r)){showToast('Place next to your world to expand');return}if(mode==='expand'){if(state.coins<75){showToast('Need 75 coins to expand');return}state.coins-=75;selected='field'}if(mode==='build'){placeBuildingAt(q,r);return}placeTile(q,r,selected)}
function placeTile(q,r,type){const def=tileDefs[type];if(state.coins<(def.cost||0)){showToast('Not enough coins ✨');return}if(state.tiles[key(q,r)])return;state.coins-=def.cost||0;state.tiles[key(q,r)]=type;state.xp+=12;state.mission=Math.min(3,state.mission+1);if(Object.keys(state.tiles).length%3===0)state.stars+=1;selectedCell=[q,r];save();rebuildWorld();renderHUD();showToast(`${type[0].toUpperCase()+type.slice(1)} added! +12 XP`);}
function collectFrom(q,r,type){const gains=tileDefs[type]?.res||{};let count=0;Object.entries(gains).forEach(([name,amount])=>{const available=state.resources[name]||0;const actual=Math.min(amount,Math.max(1,available<1?1:amount));state.resources[name]=available+actual;count+=actual});state.coins+=2;state.xp+=4;state.mission=Math.min(3,state.mission+1);if(type==='farm')state.harvests++;save();renderHUD();showToast(`Collected ${Object.entries(gains).map(([k,v])=>`${itemEmoji[k]} +${v}`).join('  ')}`);}
function canPay(cost,coins=0){return state.coins>=coins&&Object.entries(cost||{}).every(([k,v])=>(state.resources[k]||0)>=v)}function pay(cost,coins=0){state.coins-=coins;Object.entries(cost||{}).forEach(([k,v])=>state.resources[k]-=v)}
function placeBuildingAt(q,r){const k=key(q,r);if(state.buildings[k]){showToast('This tile already has a building');return}if(!selectedBuilding){openModal('build');return}const b=buildings[selectedBuilding];if(!canPay(b.cost,b.coins)){showToast('You need more materials for that');return}pay(b.cost,b.coins);state.buildings[k]=selectedBuilding;state.xp+=20;selectedBuilding=null;mode='tile';save();rebuildWorld();renderHUD();closeModal();showToast('A new building is ready! +20 XP');}
function renderHUD(){const t=dict[state.language]||dict.en;$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(t[k])el.textContent=t[k]});$('#coins').textContent=state.coins;$('#stars').textContent=state.stars;$('#wood').textContent=state.resources.wood;$('#stone').textContent=state.resources.stone;$('#level').textContent=state.level;$('#xp-label').textContent=`${state.xp%100} / 100 XP`;$(`#xp-fill`).style.width=`${state.xp%100}%`;$('#quest-progress').textContent=state.language==='pt'?`Coletar 3 recursos · ${state.mission}/3`:`Gather 3 resources · ${state.mission}/3`;$('#welcome-level').textContent=`${state.language==='pt'?'NÍVEL':'LEVEL'} ${state.level}`;$('#welcome-tiles').textContent=`${Object.keys(state.tiles).length} TILES`;resources.forEach(k=>{const el=$(`[data-resource="${k}"]`);if(el)el.textContent=state.resources[k]});}
function grantXP(n){state.xp+=n;while(state.xp>=100){state.xp-=100;state.level++;state.coins+=50;state.stars++;showToast(`Level ${state.level}! +50 coins 🎉`)}renderHUD()}
function save(){while(state.xp>=100){state.xp-=100;state.level++;state.coins+=50;state.stars++}state.last=Date.now();localStorage.setItem('terraHexaSave',JSON.stringify(state));renderHUD()}
function showToast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}

let selectedBuilding=null;function openModal(kind){modalOpen=true;const root=$('#modal-root');root.innerHTML='';const backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});const card=document.createElement('div');card.className='modal-card';backdrop.append(card);root.append(backdrop);const title=({build:'Build your village',market:'Little market',inventory:'Your backpack',missions:'Goals & rewards',settings:'Settings'})[kind]||kind;card.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close-modal" aria-label="Close">×</button></div>`;card.querySelector('.close-modal').onclick=closeModal;
if(kind==='build'){card.insertAdjacentHTML('beforeend',`<p class="modal-subtitle">Choose a building, then tap a tile in your world.</p><div class="build-grid">${Object.entries(buildings).map(([id,b])=>`<button class="build-card" data-building="${id}"><span class="emoji">${b.emoji}</span><b>${b.name}</b><small>${Object.entries(b.cost).map(([k,v])=>`${itemEmoji[k]} ${v}`).join(' · ')}</small><em>🪙 ${b.coins}${b.pop?` · +${b.pop} villagers`:''}</em></button>`).join('')}</div><div style="display:flex;gap:8px;margin-top:12px"><button class="modal-action secondary" id="expand-btn">＋ Expand land · 🪙 75</button><button class="modal-action secondary" id="remove-btn">⌫ Remove tile</button></div>`);card.querySelectorAll('[data-building]').forEach(btn=>btn.onclick=()=>{selectedBuilding=btn.dataset.building;mode='build';closeModal();showToast(`Tap a tile for your ${buildings[selectedBuilding].name}`)});card.querySelector('#expand-btn').onclick=()=>{mode='expand';closeModal();showToast('Tap a glowing space to expand · 75 coins')};card.querySelector('#remove-btn').onclick=()=>{mode='remove';closeModal();showToast('Tap a tile to remove it')};}
