let state=loadState(),scene,camera,renderer,raycaster,pointer,world,ground,selected='field',mode='tile',selectedBuilding=null,selectedCell=null,zoom=8.6,angle=0,ghost=null,clock=new THREE.Clock(),props=[],tileMeshes=new Map(),toastTimer,drag=null;
