function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();props.forEach(d=>{if(d.rotate)d.obj.rotation.z=t*.75;if(d.water)d.obj.scale.setScalar(.85+Math.sin(t*1.6+d.phase)*.18);if(d.sway!==undefined)d.obj.rotation.z=Math.sin(t*1.1+d.sway)*.035;if(d.boat){d.obj.position.x=1+Math.sin(t*.38)*.25;d.obj.position.z=1+Math.cos(t*.32)*.18}if(d.bird!==undefined){d.obj.position.x=-2+Math.sin(t*.35+d.bird)*.7;d.obj.position.y=2.7+Math.sin(t*4+d.bird)*.08}if(d.walk!==undefined)d.obj.position.x=-.42+d.walk*.82+Math.sin(t*.75+d.walk*3)*.06});renderer.render(scene,camera)}

