function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();props.forEach(d=>{if(d.rotate)d.obj.rotation.z=t*.75;if(d.water)d.obj.scale.setScalar(.85+Math.sin(t*1.6+d.phase)*.18);if(d.sway!==undefined)d.obj.rotation.z=Math.sin(t*1.1+d.sway)*.035;if(d.boat){d.obj.position.x=1+Math.sin(t*.38)*.25;d.obj.position.z=1+Math.cos(t*.32)*.18}if(d.bird!==undefined){d.obj.position.x=-2+Math.sin(t*.35+d.bird)*.7;d.obj.position.y=2.7+Math.sin(t*4+d.bird)*.08}if(d.walk!==undefined)d.obj.position.x=-.42+d.walk*.82+Math.sin(t*.75+d.walk*3)*.06});renderer.render(scene,camera)}
function neighbors(q,r){return [[1,0],[1,-1],[0,-1],[-1,0],[-1,1],[0,1]].map(([a,b])=>[q+a,r+b])}function adjacent(q,r){return neighbors(q,r).some(([a,b])=>state.tiles[key(a,b)])}
function nearest(p){const s=1.16,q=(Math.sqrt(3)/3*p.x-1/3*p.z)/s,r=2/3*p.z/s,x=q,z=r,y=-x-z;let rx=Math.round(x),ry=Math.round(y),rz=Math.round(z),dx=Math.abs(rx-x),dy=Math.abs(ry-y),dz=Math.abs(rz-z);if(dx>dy&&dx>dz)rx=-ry-rz;else if(dy>dz)ry=-rx-rz;else rz=-rx-ry;return[rx,rz]}
function point(e){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(e.clientX-rect.left)/rect.width*2-1;pointer.y=-(e.clientY-rect.top)/rect.height*2+1;raycaster.setFromCamera(pointer,camera)}
function cellAt(e){point(e);const hit=raycaster.intersectObject(ground)[0];return hit?nearest(hit.point):null}
function onMove(e){if(drag&&!drag.moved&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>10)drag.moved=true;if(drag&&drag.moved){angle+=(e.clientX-drag.x)*.006;drag.x=e.clientX;updateCamera();return}const cell=cellAt(e);if(!cell)return;const[q,r]=cell;if(state.tiles[key(q,r)]||!adjacent(q,r)){if(ghost){world.remove(ghost);ghost=null}return}if(!ghost){ghost=new THREE.Mesh(new THREE.CylinderGeometry(1.12,1.12,.1,6),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.48,depthWrite:false}));ghost.rotation.y=Math.PI/6;world.add(ghost)}const p=pos(q,r);ghost.position.set(p.x,.03,p.z);ghost.material.color.setHex(mode==='tile'?tileDefs[selected].color:0x9fe0a2)}
function onPointer(e){if(e.button!==undefined&&e.button!==0)return;drag={x:e.clientX,startX:e.clientX,startY:e.clientY,moved:false};renderer.domElement.setPointerCapture?.(e.pointerId)}
function onPointerUp(e){if(!drag)return;const moved=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>10;drag=null;if(moved)return;const cell=cellAt(e);if(!cell)return;selectedCell=cell;const[q,r]=cell,k=key(q,r);if(state.tiles[k]){if(mode==='remove'){removeTile(q,r);return}if(mode==='gather'){gather(q,r);return}if(mode==='building'){placeBuilding(q,r);return}toast(`${tileLabel(state.tiles[k])} · ${q}, ${r}`);return}if(!adjacent(q,r)){toast('Place next to an existing tile');return}if(mode==='tile')placeTile(q,r);else if(mode==='building')toast('Choose an existing tile for your building');else if(mode==='expand')placeTile(q,r,'field')}
function spendCoins(n){if(state.coins<n){toast('Not enough coins');return false}state.coins-=n;return true}function canAfford(cost){for(const[res,n]of Object.entries(cost))if((state.resources[res]||0)<n){toast(`Need ${n} ${res}`);return false}return true}
function placeTile(q,r,type=selected){const d=tileDefs[type];if(d.cost&&!spendCoins(d.cost))return;state.tiles[key(q,r)]=type;state.xp+=12;if(type!=='field')state.stars++;checkLevel();rebuild();updateUI();save();toast('Tile placed!')}
function placeBuilding(q,r,type=selectedBuilding){if(!type)return;const b=buildings[type],k=key(q,r);if(!state.tiles[k])return;if(state.buildings[k]){toast('This tile already has a building');return}if(!canAfford(b.cost)||!spendCoins(b.coins))return;for(const[res,n]of Object.entries(b.cost))state.resources[res]-=n;state.buildings[k]=type;state.xp+=20;checkLevel();rebuild();updateUI();save();closeModal();toast(`${b.name} built!`)}
function removeTile(q,r){const k=key(q,r);if(Object.keys(state.tiles).length<=1){toast('Keep at least one tile');return}delete state.tiles[k];delete state.buildings[k];state.xp+=3;checkLevel();mode='tile';rebuild();updateUI();save();toast('Tile removed')}
function gather(q,r){const t=state.tiles[key(q,r)];if(!t)return;const drops=tileDefs[t].res;let n=0;for(const[res,v]of Object.entries(drops)){state.resources[res]=(state.resources[res]||0)+v;n+=v}state.harvests+=n;state.mission=Math.min(3,state.mission+n);state.xp+=5;checkLevel();updateUI();save();toast(`Collected ${Object.entries(drops).map(([k,v])=>`${itemEmoji[k]} +${v}`).join('  ')}`)}
function collect(){let n=0;for(const t of Object.values(state.tiles))for(const[res,v]of Object.entries(tileDefs[t].res)){state.resources[res]=(state.resources[res]||0)+v;n+=v}state.harvests+=n;state.mission=Math.min(3,state.mission+n);state.xp+=Math.min(n,12);checkLevel();updateUI();save();toast(`Collected ${n} resources!`)}
function checkLevel(){while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.coins+=50;state.stars+=2;toast(`Level ${state.level}! +🪙50`)}}
function regenerate(){for(const t of Object.values(state.tiles))for(const[res,n]of Object.entries(tileDefs[t].res))state.resources[res]=Math.min(999,(state.resources[res]||0)+Math.max(1,Math.floor(n/3)));for(const b of Object.values(state.buildings))if(buildings[b]?.production)state.resources[buildings[b].production]++;updateUI();save()}

