function openBuild(){const pt=state.language==='pt';const options=Object.entries(buildings).map(([id,b])=>`<button class="modal-row" data-action="select-building" data-value="${id}"><span class="modal-emoji">${b.emoji}</span><span class="modal-row-copy"><b>${pt?({house:'Casinha',farmhouse:'Sítio',bridge:'Ponte pequena',market:'Barraca de feira',mill:'Moinho',warehouse:'Depósito'}[id]):b.name}</b><small>${costText(b.cost)} · 🪙 ${b.coins}</small></span><span class="row-arrow">›</span></button>`).join('');openModal(pt?'Construir':'Build something lovely',`${options}<div class="modal-divider"></div><button class="modal-row" data-action="mode-expand"><span class="modal-emoji">➕</span><span class="modal-row-copy"><b>${pt?'Expandir com um campo':'Expand with a field'}</b><small>${pt?'Grátis · toque em um espaço vizinho vazio':'Free · tap an empty neighboring space'}</small></span><span class="row-arrow">›</span></button><button class="modal-row" data-action="mode-remove"><span class="modal-emoji">🧹</span><span class="modal-row-copy"><b>${pt?'Remover terreno':'Remove a tile'}</b><small>${pt?'Limpe um terreno e sua construção':'Clear a tile and its building'}</small></span><span class="row-arrow">›</span></button>`)}
function openInventory(){const pt=state.language==='pt';const rows=resourceNames.map(k=>`<div class="inventory-row"><span>${itemEmoji[k]} ${pt?({wood:'Madeira',stone:'Pedra',water:'Água',fish:'Peixe',wheat:'Trigo',vegetables:'Vegetais',fruits:'Frutas',flowers:'Flores',clay:'Argila',minerals:'Minérios'}[k]):k[0].toUpperCase()+k.slice(1)}</span><b>${state.resources[k]||0}</b></div>`).join('');openModal(pt?'Seus recursos':'Your resources',`<div class="inventory-grid">${rows}</div><p class="modal-note">${pt?'Os recursos se regeneram com o tempo. Colete no seu mundo quando quiser.':'Resources regenerate over time. Gather from your world whenever you like.'}</p>`)}
function openMarket(){const rates={wood:3,stone:4,water:2,fish:3,wheat:2,vegetables:3,fruits:3,flowers:2,clay:3,minerals:7},pt=state.language==='pt';const rows=resourceNames.map(k=>`<button class="modal-row" data-action="sell" data-value="${k}"><span class="modal-emoji">${itemEmoji[k]}</span><span class="modal-row-copy"><b>${pt?'Vender':'Sell'} ${k}</b><small>${pt?'Você tem':'You have'} ${state.resources[k]||0} · 🪙 ${rates[k]} ${pt?'cada':'each'}</small></span><span class="row-arrow">＋</span></button>`).join('');openModal(pt?'Feira da vila':'Village market',`<p class="modal-note">${pt?'Troque 1 item por vez por moedas.':'Trade 1 item at a time for coins.'}</p>${rows}<button class="modal-primary" data-action="buy-seed">${pt?'Comprar sementes · 🪙 20':'Buy a seed bundle · 🪙 20'}</button>`)}
function openMissions(){const done=state.mission>=3,pt=state.language==='pt';openModal(pt?'Suas pequenas metas':'Your little goals',`<div class="mission-card"><span class="mission-symbol">${done?'✅':'✦'}</span><div><b>${pt?'Colete 3 recursos':'Gather 3 resources'}</b><p>${Math.min(3,state.mission)} / 3 · ${done?(pt?'Recompensa disponível':'Reward claimed'):(pt?'Recompensa: 🪙 35 + ⭐ 1':'Reward: 🪙 35 + ⭐ 1')}</p></div></div><button class="modal-primary" data-action="claim" ${done?'':'disabled'}>${done?(pt?'Resgatar recompensa':'Claim reward'):(pt?'Continue coletando':'Keep gathering')}</button><div class="mission-card"><span class="mission-symbol">🏡</span><div><b>${pt?'Faça sua vila crescer':'Grow your village'}</b><p>${Object.keys(state.buildings).length} ${pt?'construções colocadas':'buildings placed'}</p></div></div>`)}
function openSettings(){const pt=state.language==='pt';openModal(pt?'Configurações':'Settings',`<div class="settings-row"><span>Language / Idioma</span><select id="language-select"><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="pt" ${state.language==='pt'?'selected':''}>Português (Brasil)</option></select></div><div class="settings-row"><span>${pt?'Efeitos sonoros':'Sound effects'}</span><button class="toggle-button" data-action="sound">${state.sound?(pt?'Ligado':'On'):(pt?'Desligado':'Off')}</button></div><button class="modal-row" data-action="save"><span class="modal-emoji">💾</span><span class="modal-row-copy"><b>${pt?'Salvar progresso':'Save progress'}</b><small>${pt?'Salvo neste dispositivo':'Stored on this device'}</small></span><span class="row-arrow">›</span></button><button class="modal-row danger-row" data-action="reset"><span class="modal-emoji">🔄</span><span class="modal-row-copy"><b>${pt?'Começar um novo mundo':'Start a new world'}</b><small>${pt?'O progresso salvo será substituído':'This will replace this device’s save'}</small></span><span class="row-arrow">›</span></button>`);$('#language-select').onchange=e=>{state.language=e.target.value;applyLanguage();save();openSettings()}}
function modalAction(action,value){const pt=state.language==='pt';if(action==='select-building'){selectedBuilding=value;mode='building';closeModal();updateUI();toast(`${buildings[value].name} · ${pt?'toque em um terreno':'tap a tile'}`)}else if(action==='mode-expand'){mode='expand';selectedBuilding=null;closeModal();updateUI()}else if(action==='mode-remove'){mode='remove';selectedBuilding=null;closeModal();updateUI()}else if(action==='sell'){if((state.resources[value]||0)<1){toast(pt?'Recursos insuficientes':'Not enough resources');return}const rate={wood:3,stone:4,water:2,fish:3,wheat:2,vegetables:3,fruits:3,flowers:2,clay:3,minerals:7}[value];state.resources[value]--;state.coins+=rate;save();openMarket();updateUI()}else if(action==='buy-seed'){if(!spendCoins(20))return;state.resources.wheat+=3;state.resources.flowers+=2;save();openMarket();updateUI()}else if(action==='claim'){if(state.mission<3)return;state.mission-=3;state.coins+=35;state.stars++;save();updateUI();openMissions();toast(pt?'Meta concluída! +🪙35 +⭐1':'Goal complete! +🪙35 +⭐1')}else if(action==='sound'){state.sound=!state.sound;save();openSettings()}else if(action==='save'){save();closeModal();toast(pt?'Progresso salvo':'Progress saved')}else if(action==='reset'){if(confirm(pt?'Começar um novo mundo? Seu progresso atual será substituído.':'Start a fresh world? Your current progress will be replaced.')){state=fresh();save();rebuild();applyLanguage();closeModal();$('#welcome-overlay').classList.remove('hidden')}}}
function bindUI(){
  $$('.tile-option').forEach(b=>b.onclick=()=>{selected=b.dataset.tile;mode='tile';selectedBuilding=null;updateUI()});
  $('#build-menu-button').onclick=openBuild;$('#market-button').onclick=openMarket;$('#missions-button').onclick=openMissions;$('#inventory-button').onclick=openInventory;$('#settings-button').onclick=openSettings;
  $('#collect-button').onclick=collect;$('#rotate-tile').onclick=()=>{angle+=Math.PI/3;updateCamera()};$('#rotate-left').onclick=()=>{angle-=Math.PI/3;updateCamera()};$('#rotate-right').onclick=()=>{angle+=Math.PI/3;updateCamera()};$('#zoom-in').onclick=()=>{zoom=Math.max(6,zoom-.7);updateCamera()};$('#zoom-out').onclick=()=>{zoom=Math.min(14,zoom+.7);updateCamera()};
  $('#quest-button').onclick=openMissions;$('#home-button').onclick=()=>{$('#welcome-overlay').classList.remove('hidden');$('#welcome-level').textContent=`${state.language==='pt'?'NÍVEL':'LEVEL'} ${state.level}`;$('#welcome-tiles').textContent=`${Object.keys(state.tiles).length} ${state.language==='pt'?'TERRENOS':'TILES'}`};
  $('#continue-button').onclick=()=>{state.hasPlayed=true;$('#welcome-overlay').classList.add('hidden');save()};$('#new-world-button').onclick=()=>{if(confirm(state.language==='pt'?'Começar um novo mundo? Seu progresso atual será substituído.':'Start a fresh world? Your current progress will be replaced.')){state=fresh();state.hasPlayed=true;save();rebuild();applyLanguage();$('#welcome-overlay').classList.add('hidden')}};
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});window.addEventListener('beforeunload',save);
}
init();

