content.text:
.bottom-dock{position:absolute;z-index:4;bottom:0;left:0;right:0;padding:14px 14px calc(env(safe-area-inset-bottom) + 8px);border-radius:24px 24px 0 0;background:#fffdf6f5;box-shadow:0 -8px 28px #466c5022;backdrop-filter:blur(12px)}
.welcome-overlay{position:absolute;inset:0;z-index:10;background:linear-gradient(180deg,#d9f0dc2e,#244c3c45);display:flex;align-items:center;justify-content:center;padding:24px;backdrop-filter:blur(4px);transition:opacity .4s,visibility .4s}
.welcome-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.modal-backdrop{position:absolute;z-index:8;inset:0;background:#234b3b56;display:flex;align-items:flex-end;justify-content:center;padding:14px;backdrop-filter:blur(3px)}
.modal-card{width:100%;max-width:440px;max-height:76%;overflow:auto;background:#fffdf7;border-radius:23px;padding:20px;box-shadow:0 20px 60px #214a3933;animation:rise .25s ease}
.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}
.modal-head h2{margin:0;font:800 19px Nunito,sans-serif;color:#315d48}
.modal-subtitle{font-size:11px;color:#82948a;margin:-8px 0 14px}
.modal-action{display:inline-flex;align-items:center;justify-content:center;gap:5px;background:#4e9a72;color:white;border-radius:10px;padding:7px 9px;margin-top:8px;font-size:9px;font-weight:800}
.modal-action.secondary{background:#eef5e9;color:#51805e}
.hidden{display:none!important}
.bottom-dock{border-radius:24px 24px 28px 28px}
.bottom-dock{padding-top:10px}

.quest-arrow{font-size:20px;color:#90aa97}
.eyebrow{font-size:8px;font-weight:800;letter-spacing:.16em;color:#9bad9e}
.toast{position:absolute;z-index:20;left:50%;top:46%;transform:translate(-50%,10px);background:#315c48;color:white;border-radius:13px;padding:10px 15px;font-size:11px;box-shadow:var(--shadow);opacity:0;pointer-events:none;transition:.25s;white-space:nowrap}
.modal-backdrop{position:absolute;z-index:8;inset:0;background:#234b3b56;display:flex;align-items:flex-end;justify-content:center;padding:14px;backdrop-filter:blur(3px)}
.modal-card{width:100%;max-width:440px;max-height:76%;overflow:auto;background:#fffdf7;border-radius:23px;padding:20px;box-shadow:0 20px 60px #214a3933;animation:rise .25s ease}
.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}
.close-modal{width:30px;height:30px;border-radius:10px;background:#edf4e9;color:#60876c;font-size:18px}
.modal-subtitle{font-size:11px;color:#82948a;margin:-8px 0 14px}
.inventory-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.inventory-card{padding:12px;border:1px solid #e9eee5;border-radius:15px;background:white;text-align:left;min-height:90px}
